import axios from '@/utils/axiosConfig';
import UserInfoDialog from '@/components/UserInfoDialog.vue';
export default {
  name: 'LeaveApproval',
  components: {
    UserInfoDialog
  },
  props: {
    records: Array,
    approverLevel: {
      type: Number,
      default: 0
    },
    disabled: {
      type: Boolean,
      default: false
    },
    isAdmin: {
      type: Boolean,
      default: false
    }
  },
  inject: ['$toast'],
  created() {
    this.$http = axios;
  },
  data() {
    return {
      showWorkDetailsDialog: false,
      selectedWorkDetails: '',
      showAttachmentsDialog: false,
      selectedAttachments: [],
      fullImageDialog: false,
      fullImageUrl: '',
      leaveTypes: [],
      showUserDialog: false,
      selectedUserId: null,
      showCancelReasonDialog: false,
      selectedCancelReason: '',
      workHours: {
        start_time: '09:00',
        end_time: '18:00',
        lunch_start: '12:00',
        lunch_end: '13:00'
      },
      workHoursCache: {}
    };
  },
  async mounted() {
    await this.loadLeaveTypes();
    await this.loadWorkHours();
    if (this.records?.length) await this.preloadWorkHoursForRecords(this.records);
  },
  watch: {
    records(newRecords) {
      if (newRecords?.length) this.preloadWorkHoursForRecords(newRecords);
    }
  },
  methods: {
    showUserInfo(userId) {
      if (userId) {
        this.selectedUserId = userId;
        this.showUserDialog = true;
      }
    },
    async loadWorkHours() {
      try {
        const role = localStorage.getItem('soc_role') || 'user';
        const userId = localStorage.getItem('soc_user_id');
        this.workHours = await this.fetchWorkHoursForUser(userId, role);
      } catch {/* ignore */}
    },
    async fetchWorkHoursForUser(userId, role) {
      const fmt = t => t?.substring(0, 5);
      if (userId) {
        try {
          const res = await this.$http.get('/api/settings/user-work-hours');
          const found = res.data.find(u => u.user_id === parseInt(userId));
          if (found) return {
            start_time: fmt(found.start_time),
            end_time: fmt(found.end_time),
            lunch_start: fmt(found.lunch_start),
            lunch_end: fmt(found.lunch_end)
          };
        } catch {/* fallthrough */}
      }
      return this.getWorkHoursForRole(role);
    },
    async getWorkHoursForRole(role) {
      if (!role) return this.workHours;
      if (this.workHoursCache[role]) return this.workHoursCache[role];
      try {
        const response = await this.$http.get(`/api/settings/role-work-hours/${role}`);
        const wh = {
          start_time: response.data.start_time?.substring(0, 5) || '09:00',
          end_time: response.data.end_time?.substring(0, 5) || '18:00',
          lunch_start: response.data.lunch_start?.substring(0, 5) || '12:00',
          lunch_end: response.data.lunch_end?.substring(0, 5) || '13:00'
        };
        this.workHoursCache[role] = wh;
        return wh;
      } catch {/* ignore */}
      return this.workHours;
    },
    async preloadWorkHoursForRecords(records) {
      // โหลด user-level work hours ทั้งหมดในครั้งเดียว แล้ว cache ด้วย user_id
      try {
        const res = await this.$http.get('/api/settings/user-work-hours');
        const fmt = t => t?.substring(0, 5);
        res.data.forEach(u => {
          this.workHoursCache[`user_${u.user_id}`] = {
            start_time: fmt(u.start_time),
            end_time: fmt(u.end_time),
            lunch_start: fmt(u.lunch_start),
            lunch_end: fmt(u.lunch_end)
          };
        });
      } catch {/* ignore */}
      const roles = [...new Set(records.map(r => r.employee_role).filter(Boolean))];
      await Promise.all(roles.map(role => this.getWorkHoursForRole(role)));
    },
    calculateHours(data) {
      const wh = this.workHoursCache[`user_${data.user_id}`] || this.workHoursCache[data.employee_role] || this.workHours;
      if (data.employee_role && !this.workHoursCache[data.employee_role]) {
        this.getWorkHoursForRole(data.employee_role);
      }
      const start = new Date(data.start_datetime);
      const end = new Date(data.end_datetime);
      const [ws, wsm = 0] = wh.start_time.split(':').map(Number);
      const [we, wem = 0] = wh.end_time.split(':').map(Number);
      const [ls, lsm = 0] = wh.lunch_start.split(':').map(Number);
      const [le, lem = 0] = wh.lunch_end.split(':').map(Number);
      const wsMin = ws * 60 + wsm,
        weMin = we * 60 + wem;
      const lsMin = ls * 60 + lsm,
        leMin = le * 60 + lem;
      const fullDayMinutes = lsMin - wsMin + (weMin - leMin);
      const startDate = new Date(start);
      startDate.setHours(0, 0, 0, 0);
      const endDate = new Date(end);
      endDate.setHours(0, 0, 0, 0);
      let totalMinutes = 0;
      const calcMins = (s, e) => {
        const sMin = s.getHours() * 60 + s.getMinutes();
        const eMin = e.getHours() * 60 + e.getMinutes();
        let m = 0;
        const mS = Math.max(sMin, wsMin),
          mE = Math.min(eMin, lsMin);
        if (mE > mS) m += mE - mS;
        const aS = Math.max(sMin, leMin),
          aE = Math.min(eMin, weMin);
        if (aE > aS) m += aE - aS;
        if (m >= fullDayMinutes * 0.9) return fullDayMinutes;
        return Math.max(0, m);
      };
      if (startDate.getTime() === endDate.getTime()) {
        totalMinutes = calcMins(start, end);
      } else {
        const cur = new Date(startDate);
        while (cur <= endDate) {
          const day = cur.getDay();
          if (day !== 0 && day !== 6) {
            if (cur.getTime() === startDate.getTime()) {
              const de = new Date(cur);
              de.setHours(we, wem, 0, 0);
              totalMinutes += calcMins(start, de);
            } else if (cur.getTime() === endDate.getTime()) {
              const ds = new Date(cur);
              ds.setHours(ws, wsm, 0, 0);
              totalMinutes += calcMins(ds, end);
            } else {
              totalMinutes += fullDayMinutes;
            }
          }
          cur.setDate(cur.getDate() + 1);
        }
      }
      const hours = totalMinutes / 60;
      return Number.isInteger(hours) ? hours : hours.toFixed(1);
    },
    async loadLeaveTypes() {
      try {
        const response = await this.$http.get('/api/leave/leave-types');
        this.leaveTypes = response.data;
      } catch {// ignore
      }
    },
    getLeaveTypeColor(type) {
      const leaveType = this.leaveTypes.find(lt => lt.value === type);
      return leaveType?.color || '#6c757d';
    },
    showWorkDetails(workDetails) {
      this.selectedWorkDetails = workDetails;
      this.showWorkDetailsDialog = true;
    },
    showAttachments(attachments) {
      this.selectedAttachments = attachments || [];
      this.showAttachmentsDialog = true;
    },
    async downloadFile(fileName) {
      try {
        const response = await this.$http.get(`/api/files/download/${fileName}`, {
          responseType: 'blob'
        });
        const url = window.URL.createObjectURL(new Blob([response.data]));
        const link = document.createElement('a');
        link.href = url;
        const originalName = fileName.split('-').slice(2).join('-') || fileName;
        link.download = originalName;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);
        this.$toast.add({
          severity: 'success',
          summary: 'ดาวน์โหลดสำเร็จ',
          detail: originalName,
          life: 3000
        });
      } catch {
        this.$toast.add({
          severity: 'error',
          summary: 'เกิดข้อผิดพลาด',
          detail: 'ไม่สามารถดาวน์โหลดไฟล์ได้',
          life: 3000
        });
      }
    },
    isImageFile(fileName) {
      const extension = fileName.split('.').pop()?.toLowerCase();
      return ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'].includes(extension);
    },
    getFileUrl(fileName) {
      const token = localStorage.getItem('soc_token');
      return `/api/files/download/${fileName}?token=${token}`;
    },
    viewFullImage(fileName) {
      this.fullImageUrl = this.getFileUrl(fileName);
      this.fullImageDialog = true;
    },
    getFileIcon(fileName) {
      const extension = fileName.split('.').pop()?.toLowerCase();
      const icons = {
        pdf: 'pi pi-file-pdf',
        doc: 'pi pi-file-word',
        docx: 'pi pi-file-word',
        xls: 'pi pi-file-excel',
        xlsx: 'pi pi-file-excel',
        jpg: 'pi pi-image',
        jpeg: 'pi pi-image',
        png: 'pi pi-image',
        gif: 'pi pi-image'
      };
      return icons[extension] || 'pi pi-file';
    },
    getFileType(fileName) {
      const extension = fileName.split('.').pop()?.toLowerCase();
      const types = {
        pdf: 'PDF Document',
        doc: 'Word Document',
        docx: 'Word Document',
        xls: 'Excel Spreadsheet',
        xlsx: 'Excel Spreadsheet',
        jpg: 'JPEG Image',
        jpeg: 'JPEG Image',
        png: 'PNG Image',
        gif: 'GIF Image'
      };
      return types[extension] || 'Unknown File';
    },
    formatDateTime(datetime) {
      if (!datetime) return '-';
      const date = new Date(datetime);
      return date.toLocaleString('th-TH', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        timeZone: 'Asia/Bangkok'
      });
    },
    formatDate(datetime) {
      if (!datetime) return '-';
      const date = new Date(datetime);
      return date.toLocaleDateString('th-TH', {
        day: '2-digit',
        month: '2-digit',
        timeZone: 'Asia/Bangkok'
      });
    },
    calculateDays(startDateTime, endDateTime) {
      if (!startDateTime || !endDateTime) return 0;
      const start = new Date(startDateTime);
      const end = new Date(endDateTime);
      const diffMs = end - start;
      const diffHours = diffMs / (1000 * 60 * 60);
      // คำนวณเป็นวัน (8 ชม. = 1 วัน)
      return diffHours / 8;
    },
    getLeaveTypeLabel(type) {
      const types = {
        sick: 'ลาป่วย',
        personal: 'ลากิจ',
        vacation: 'ลาพักร้อน',
        maternity: 'ลาคลอด',
        other: 'ลาอื่นๆ'
      };
      return types[type] || type;
    },
    showCancelReason(reason) {
      this.selectedCancelReason = reason;
      this.showCancelReasonDialog = true;
    },
    canApproveRecord(record) {
      // ต้องเป็น status ที่รออนุมัติเท่านั้น
      if (record.status !== 'pending' && record.status !== 'pending_level2' && record.status !== 'cancel') return false;

      // การยกเลิกต้องเป็น Level 2 เท่านั้น
      if (record.status === 'cancel') {
        return this.approverLevel === 2 || this.approverLevel === 3;
      }

      // Admin approve/reject ได้ทุกรายการ
      if (this.isAdmin) return true;

      // approverLevel: 0 = ไม่มีสิทธิ์, 1 = level 1 only, 2 = level 2 only, 3 = ทั้งสอง
      if (this.approverLevel === 0) return false;

      // มีสิทธิ์ทั้งสอง level
      if (this.approverLevel === 3) return true;

      // Level 1 approver สามารถ approve ได้เฉพาะ status = 'pending'
      if (this.approverLevel === 1 && record.status === 'pending') return true;

      // Level 2 approver สามารถ approve ได้เฉพาะ status = 'pending_level2'
      if (this.approverLevel === 2 && record.status === 'pending_level2') return true;
      return false;
    },
    getApproveTooltip(record) {
      if (record.status === 'pending') return 'อนุมัติขั้นที่ 1 (หัวหน้างาน)';
      if (record.status === 'pending_level2') return 'อนุมัติขั้นที่ 2 (HR)';
      if (record.status === 'cancel') return 'อนุมัติยกเลิก';
      return 'อนุมัติ';
    },
    async approveCancellation(leaveId) {
      this.$confirm.require({
        message: 'คุณต้องการอนุมัติการยกเลิกนี้หรือไม่?',
        header: 'ยืนยันการอนุมัติยกเลิก',
        icon: 'pi pi-check-circle',
        acceptClass: 'p-button-success',
        acceptLabel: 'อนุมัติ',
        rejectLabel: 'ยกเลิก',
        draggable: false,
        accept: async () => {
          try {
            const approverName = `${localStorage.getItem('soc_firstname')} ${localStorage.getItem('soc_lastname')}`.trim();
            const approverPosition = localStorage.getItem('soc_position') || 'ไม่ระบุตำแหน่ง';
            const approverInfo = `${approverName} (${approverPosition})`;
            await this.$http.put(`/api/leave/${leaveId}/cancel-status`, {
              action: 'approve',
              approved_by: approverInfo
            });
            this.$toast.add({
              severity: 'success',
              summary: 'สำเร็จ',
              detail: 'อนุมัติยกเลิกการลาเรียบร้อย',
              life: 3000
            });
            this.$emit('close-form');
          } catch (err) {
            this.$toast.add({
              severity: 'error',
              summary: 'อนุมัติไม่สำเร็จ',
              detail: err.response?.data?.error || 'กรุณาลองใหม่อีกครั้ง',
              life: 4000
            });
          }
        }
      });
    },
    async rejectCancellation(leaveId) {
      this.$confirm.require({
        message: 'คุณต้องการไม่อนุมัติการยกเลิกนี้หรือไม่? (การลาจะยังคงอนุมัติอยู่)',
        header: 'ยืนยันไม่อนุมัติยกเลิก',
        icon: 'pi pi-times-circle',
        acceptClass: 'p-button-danger',
        acceptLabel: 'ไม่อนุมัติ',
        rejectLabel: 'ยกเลิก',
        draggable: false,
        accept: async () => {
          try {
            await this.$http.put(`/api/leave/${leaveId}/cancel-status`, {
              action: 'reject'
            });
            this.$toast.add({
              severity: 'info',
              summary: 'สำเร็จ',
              detail: 'ไม่อนุมัติการยกเลิก',
              life: 3000
            });
            this.$emit('close-form');
          } catch (err) {
            this.$toast.add({
              severity: 'error',
              summary: 'ดำเนินการไม่สำเร็จ',
              detail: err.response?.data?.error || 'กรุณาลองใหม่อีกครั้ง',
              life: 4000
            });
          }
        }
      });
    }
  }
};
